// Obtener workflows del input
const input = $input.all()[0].json;
let workflows = [];

if (input.data && Array.isArray(input.data)) {
  workflows = input.data;
}

// Ordenar workflows alfabéticamente por nombre
workflows.sort((a, b) => {
  const nameA = (a.name || '').toLowerCase();
  const nameB = (b.name || '').toLowerCase();
  return nameA.localeCompare(nameB);
});

// Construir la URL del POST
const webhookUrl = $execution.resumeUrl || '';
let baseUrl = '';
let postUrl = '';

if (webhookUrl) {
  const urlMatch = webhookUrl.match(/(https?:\/\/[^\/]+)/);
  if (urlMatch) {
    baseUrl = urlMatch[1];
    postUrl = baseUrl + '/webhook/deployment-submit';
  }
}

if (!postUrl) {
  postUrl = '/webhook/deployment-submit';
}

console.log('Base URL:', baseUrl);
console.log('POST URL final:', postUrl);

