// Procesar todos los workflows que llegan
const allWorkflows = $input.all();

const cleaned = allWorkflows.map(item => {
  const dirtyWorkflow = item.json;

  // Preservar _originalQaId temporalmente
  const originalQaId = dirtyWorkflow._originalQaId;

  const cleanWorkflow = {
    name: dirtyWorkflow.name,
    nodes: dirtyWorkflow.nodes,
    connections: dirtyWorkflow.connections,
    active: dirtyWorkflow.active || false
  };

  // Solo agregar tags si existen y no está vacío
  if (dirtyWorkflow.tags && Array.isArray(dirtyWorkflow.tags) && dirtyWorkflow.tags.length > 0) {
    cleanWorkflow.tags = dirtyWorkflow.tags;
  }

  // Para CREATE, solo incluir executionOrder en settings (sin callerPolicy)
  if (dirtyWorkflow.settings && dirtyWorkflow.settings.executionOrder) {
    cleanWorkflow.settings = {
      executionOrder: dirtyWorkflow.settings.executionOrder
    };
  }

  // NO incluir: pinData, staticData, meta - causan problemas en CREATE

  // Agregar _originalQaId de vuelta (para rastreo)
  cleanWorkflow._originalQaId = originalQaId;

  console.log('Workflow limpiado para CREATE:', cleanWorkflow.name);
  console.log('Settings enviados:', JSON.stringify(cleanWorkflow.settings || {}));

  return { json: cleanWorkflow };
});

return cleaned;

