// Verificar si hay entrada y si no proviene de error
const allResults = $input.all();

// Verificar si no hay entrada o está vacía
if (!allResults || allResults.length === 0) {
  return [];
}

// Verificar si la entrada proviene de una salida de error
// En n8n, las salidas de error suelen tener una propiedad 'error' o venir del index 1
const sourceIndex = $input.sourceIndex;
const isFromError = sourceIndex === 1; // Index 1 es típicamente la salida de error

if (isFromError) {
  // Si viene de error, pasar los datos sin marcar
  return allResults;
}

// Procesar y marcar solo si hay datos válidos
const marked = allResults.map(item => {
  // Verificar que el item tenga contenido
  if (!item.json || Object.keys(item.json).length === 0) {
    return { json: {} };
  }

  const result = item.json;
  result._deployAction = 'Creado';

  // El _originalQaId ya debería estar presente desde el workflow preparado
  // No necesitamos buscarlo nuevamente

  return { json: result };
});

return marked;

