function removeEmojis(str) {
  return str
    .replace(/[\u{1F000}-\u{1FFFF}]/gu, '')
    .replace(/[\u{2600}-\u{26FF}]/gu, '')
    .replace(/[\u{2700}-\u{27BF}]/gu, '')
    .replace(/[\u{FE00}-\u{FE0F}]/gu, '')
    .replace(/[\u{1F900}-\u{1F9FF}]/gu, '')
    .replace(/[\u{1F300}-\u{1F5FF}]/gu, '')
    .replace(/[\u{1F680}-\u{1F6FF}]/gu, '')
    .replace(/[\u{1F1E0}-\u{1F1FF}]/gu, '')
    .trim()
    .replace(/\s+/g, ' ');
}

// Función para actualizar las credenciales en los nodos
function updateNodeCredentials(node) {
  if (node.credentials) {
    Object.keys(node.credentials).forEach(credType => {
      let newId = null;

      // Caso especial para WhatsApp Trigger API
      if (credType === 'whatsAppTriggerApi') {
        const nodeNameLower = (node.name || '').toLowerCase();

        if (nodeNameLower.includes('clientes') && whatsappCredentials.clientes) {
          newId = whatsappCredentials.clientes;
          console.log(`  Nodo "${node.name}": Usando credencial WhatsApp de CLIENTES`);
        } else if (nodeNameLower.includes('domiciliarios') && whatsappCredentials.domiciliarios) {
          newId = whatsappCredentials.domiciliarios;
          console.log(`  Nodo "${node.name}": Usando credencial WhatsApp de DOMICILIARIOS`);
        } else {
          // Si no coincide con ningún patrón, mantener la original
          console.log(`  Nodo "${node.name}": WhatsApp sin patrón específico, manteniendo credencial original`);
        }
      } else {
        // Para otros tipos de credenciales, usar el mapeo normal
        if (credentialsMap[credType]) {
          newId = credentialsMap[credType];
        }
      }

      // Aplicar el cambio si se encontró un reemplazo
      if (newId) {
        const oldId = node.credentials[credType].id;
        node.credentials[credType].id = newId;
        console.log(`    Credencial ${credType} actualizada de ${oldId} a ${newId}`);
      } else if (credType !== 'whatsAppTriggerApi') {
        console.log(`  Nodo "${node.name}": Manteniendo credencial ${credType} con ID ${node.credentials[credType].id} (no hay reemplazo disponible)`);
      }
    });
  }
}

